<?php $this->assign('title', 'Produtos'); ?>
<div class="d-flex justify-content-between mb-4"><div><h1 class="h3">Produtos</h1><p class="text-body-secondary">Produtos farmacêuticos e itens de conveniência.</p></div><?= $this->Html->link('Novo produto', ['action' => 'add'], ['class' => 'btn btn-primary align-self-start']) ?></div>
